                pts.setdefault(v, []).append((r, c))
    for color, points in pts.items():
        for i, (r1, c1) in enumerate(points):
            for r2, c2 in points[i+1:]:
                if abs(r2-r1) == abs(c2-c1) and r2 != r1:
                    dr = 1 if r2 > r1 else -1
                    dc = 1 if c2 > c1 else -1
                    r, c = r1, c1
                    while True:
                        out[r][c] = color
                        if (r, c) == (r2, c2): break
                        r += dr; c += dc
    return out", "exit_code": 0, "error": null}

